// =====================================================
// CALCULAR DELAY NATURAL DE RESPUESTA (texto)
// Luna "lee" y "escribe" como una persona:
//   - una pausa para leer/pensar (aleatoria, 1.2s - 3.2s)
//   - un tiempo de tipeo proporcional a la longitud del mensaje
//   - una variacion aleatoria de +-25% para que nunca se sienta robotica
//   - tope de 20s para no dejar esperando al cliente
// El indicador "escribiendo..." dura casi todo el tipeo y desaparece justo
// antes de enviar (sensacion de que termino de escribir y toca enviar).
// =====================================================
const data = $input.first().json || {};

// 1) Texto de la respuesta (llega desde "Pulir y Auditar Respuesta")
let respuesta = "";
try {
  respuesta = data.choices?.[0]?.message?.content
    || data.textoRespuesta
    || data.content
    || data.textoLimpio
    || "";
} catch (e) {
  respuesta = "";
}
respuesta = String(respuesta || "").trim();
const longitud = respuesta.length;

// 2) Pausa de lectura/pensamiento (aleatoria)
function aleatorioEntre(min, max) {
  return min + Math.random() * (max - min);
}
const pausaLecturaSeg = aleatorioEntre(1.2, 3.2);

// 3) Tiempo de tipeo: un humano escribe ~30-45 palabras por minuto.
//    Usamos un ritmo un poco mas vivo para no hacer esperar de mas.
let tipeoSeg;
if (longitud < 40) tipeoSeg = 1.5;
else if (longitud < 90) tipeoSeg = 2.5;
else if (longitud < 160) tipeoSeg = 3.5;
else if (longitud < 260) tipeoSeg = 5.0;
else if (longitud < 400) tipeoSeg = 6.5;
else tipeoSeg = 8.0;

// 4) Total con variacion natural de +-25% y limites 2s - 20s
const variacion = 1 + aleatorioEntre(-0.25, 0.25);
let delaySegundos = (pausaLecturaSeg + tipeoSeg) * variacion;
delaySegundos = Math.max(2, Math.min(20, delaySegundos));
delaySegundos = Math.round(delaySegundos * 10) / 10;

const delayMs = Math.round(delaySegundos * 1000);

// 5) El "escribiendo..." cubre casi todo el tipeo y se apaga justo antes
//    de que llegue el mensaje.
const delayPresenciaMs = Math.max(1500, delayMs - 700);

// 6) Datos que necesitan los nodos siguientes
let numeroCliente = "";
try {
  numeroCliente = $('Webhook').first().json.body?.conversation?.meta?.sender?.identifier
    || $('Webhook').first().json.body?.sender?.identifier
    || "";
} catch (e) {
  numeroCliente = "";
}
numeroCliente = String(numeroCliente || "").split('@')[0];

return [{
  json: {
    content: respuesta,
    longitud: longitud,
    delay: delaySegundos,
    delayMs: delayMs,
    delayPresenciaMs: delayPresenciaMs,
    pausaLecturaSeg: Math.round(pausaLecturaSeg * 10) / 10,
    tipeoSeg: tipeoSeg,
    numero: numeroCliente,
    consultaLista: data.consultaLista || false,
    contactName: data.contactName || "Cliente",
    contactPhone: data.contactPhone || "",
    chatwootUrl: data.chatwootUrl || ""
  }
}];

const textoTranscrito = $input.first().json.text || "";
const webhookData = $('Webhook').first().json.body;

// Marcar el mensaje con tipo audio y timestamp
webhookData.content = `[AUDIO ${new Date().toISOString()}]: ${textoTranscrito}`;
webhookData._tipoMensaje = "audio";
webhookData._transcripcion = textoTranscrito;
webhookData._timestamp = Date.now();

return [
  {
    json: {
      body: webhookData
    }
  }
];

const items = $input.all();

for (const item of items) {
  if (item.binary && item.binary.data) {
    // Cambiar el nombre del archivo con extensión válida
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}

return items;

// =====================================================
// PREPARAR IMAGEN PARA OPENAI VISION (v2 — clasificador estricto)
// Devuelve el body de la peticion y la URL original de la foto
// (la URL se guarda en el checklist para enviarsela al Maestro).
// =====================================================
const input = $input.first();
const item = input.json || {};
const binary = input.binary || {};

let imageUrl = "";

// 1) URL publica directa (Chatwoot data_url / file_url)
let rawUrl = item.url || item.file_url || item.data_url || "";
if (!rawUrl && item.body && item.body.attachments && item.body.attachments[0]) {
  rawUrl = item.body.attachments[0].data_url || item.body.attachments[0].file_url || "";
}
if (!rawUrl && item.attachments && item.attachments[0]) {
  rawUrl = item.attachments[0].data_url || item.attachments[0].file_url || "";
}
if (rawUrl && /^https?:\/\//i.test(rawUrl)) imageUrl = rawUrl;

// 2) Binario de n8n (funciona tambien con filesystem-v2)
if (!imageUrl && binary && Object.keys(binary).length > 0) {
  const key = binary.data ? "data" : Object.keys(binary)[0];
  const mime = binary[key].mimeType || "image/jpeg";
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  imageUrl = "data:" + mime + ";base64," + buffer.toString("base64");
}

if (!imageUrl || imageUrl.indexOf("filesystem-v2") !== -1) {
  throw new Error("No se pudo extraer la imagen. Revisa el nodo 'Descargar Imagen'.");
}

const promptText = [
  "Eres un analista de imagenes para un gabinete espiritual. Analiza la foto y responde SOLO con JSON valido, sin markdown, sin texto antes ni despues, con este formato exacto:",
  '{"contenido":"rostro|pareja|palma|otro","personas_visibles":0,"es_palma":false,"manos_visibles":0,"calidad":"buena|regular|mala","descripcion":"maximo 25 palabras"}',
  "",
  "REGLAS DE CLASIFICACION:",
  '- "rostro": hay UNA sola persona visible (selfie, retrato, foto de perfil).',
  '- "pareja": hay DOS o mas personas visibles en la misma foto (pareja, matrimonio, familia). Cuenta muy bien los rostros, incluidos los del fondo o recortados.',
  '- "palma": lo principal es la palma de una mano abierta (lectura de mano). Si se ve una mano cerrada, de espaldas o un brazo, usa "otro".',
  '- "otro": cualquier otra cosa (objetos, velas, amuletos, capturas de pantalla, fotos demasiado borrosas).',
  "- personas_visibles: numero exacto de personas (0 si es una palma o un objeto).",
  "- es_palma: true solo si la palma abierta es el contenido principal de la foto.",
  "- manos_visibles: cantidad de manos que se ven (0 si no hay).",
  '- calidad: "mala" si esta borrosa, oscura o cortada al punto de no poder identificar a la persona o la palma.',
  "- descripcion: en espanol, objetiva, sin inventar nombres."
].join("\n");

const body = {
  model: "gpt-4o-mini",
  messages: [
    {
      role: "user",
      content: [
        { type: "text", text: promptText },
        { type: "image_url", image_url: { url: imageUrl } }
      ]
    }
  ],
  temperature: 0,
  max_tokens: 300,
  response_format: { type: "json_object" }
};

return [{
  json: {
    body: body,
    bodyString: JSON.stringify(body),
    fotoUrl: (rawUrl && /^https?:\/\//i.test(rawUrl)) ? rawUrl : "",
    imageUrl: imageUrl.substring(0, 80) + "..."
  }
}];

// =====================================================
// INYECTAR ANALISIS DE IMAGEN (v2)
// - Interpreta el JSON de OpenAI Vision (con respaldo por palabras clave).
// - Devuelve fotoEvento {tipo: rostro|pareja|palma|otro, ...} para que
//   "Fusionar Memoria" asigne la foto al hueco correcto segun el tipo de trabajo.
// - Reconstruye body.content para que "Consolidar Lista" vea el analisis
//   como el mensaje actual del cliente.
// =====================================================
const input = $input.first();
const raw = input.json || {};

let textoVision = "";
try {
  if (raw.choices && raw.choices[0] && raw.choices[0].message) {
    textoVision = raw.choices[0].message.content || "";
  } else if (raw.body && raw.body.choices && raw.body.choices[0]) {
    textoVision = raw.body.choices[0].message.content || "";
  } else if (typeof raw.textoAnalisis === "string") {
    textoVision = raw.textoAnalisis;
  }
} catch (e) {
  textoVision = "";
}

// --- Parseo tolerante del JSON de Vision ---
let datos = null;
if (textoVision) {
  try {
    datos = JSON.parse(textoVision);
  } catch (e) {
    const m = textoVision.match(/\{[\s\S]*\}/);
    if (m) {
      try { datos = JSON.parse(m[0]); } catch (e2) { datos = null; }
    }
  }
}

let contenido = "otro";
let personas = 0;
let esPalma = false;
let manos = 0;
let calidad = "regular";
let descripcion = "";

if (datos && typeof datos === "object") {
  contenido = String(datos.contenido || "otro").toLowerCase().trim();
  personas = parseInt(datos.personas_visibles, 10);
  if (isNaN(personas)) personas = 0;
  esPalma = datos.es_palma === true || String(datos.es_palma).toLowerCase() === "true";
  manos = parseInt(datos.manos_visibles, 10);
  if (isNaN(manos)) manos = 0;
  calidad = String(datos.calidad || "regular").toLowerCase().trim();
  descripcion = String(datos.descripcion || "").trim();
  if (contenido === "mano" || contenido === "manos") { contenido = "palma"; esPalma = true; }
} else {
  // Respaldo: si Vision no devolvio JSON util, se deduce por palabras clave.
  const t = textoVision.toLowerCase();
  if (t.indexOf("palma") !== -1 || t.indexOf("mano") !== -1) { contenido = "palma"; esPalma = true; }
  else if (t.indexOf("dos personas") !== -1 || t.indexOf("2 personas") !== -1 || t.indexOf("pareja") !== -1) { contenido = "pareja"; personas = 2; }
  else if (t.indexOf("persona") !== -1 || t.indexOf("rostro") !== -1 || t.indexOf("cara") !== -1) { contenido = "rostro"; personas = 1; }
  descripcion = textoVision.substring(0, 140);
}

// Tipo canonico usado por el checklist
let tipo = "otro";
if (esPalma || contenido === "palma") tipo = "palma";
else if (personas >= 2 || contenido === "pareja" || contenido === "dos_personas") tipo = "pareja";
else if (personas === 1 || contenido === "rostro" || contenido === "persona_unica") tipo = "rostro";

// URL de la foto (la guarda "Preparar Imagen")
let fotoUrl = "";
try { fotoUrl = $("Preparar Imagen").first().json.fotoUrl || ""; } catch (e) {}

const fotoEvento = {
  tipo: tipo,
  personas: personas,
  esPalma: esPalma,
  manos: manos,
  calidad: calidad,
  descripcion: descripcion,
  url: fotoUrl,
  cuando: new Date().toISOString()
};

const textoAnalisis =
  "[IMAGEN ANALIZADA] tipo=" + tipo +
  " personas=" + personas +
  " palma=" + (esPalma ? "si" : "no") +
  " calidad=" + calidad +
  " detalle=" + (descripcion || "sin descripcion");

// Reconstruir el body del webhook con el analisis como contenido del mensaje.
let webhookBody = {};
try { webhookBody = $("Webhook").first().json.body || {}; } catch (e) {}

const nuevoBody = JSON.parse(JSON.stringify(webhookBody || {}));
nuevoBody.content = textoAnalisis;
nuevoBody._tipoMensaje = "imagen";
nuevoBody._fotoEvento = fotoEvento;

return [{
  json: {
    body: nuevoBody,
    fotoEvento: fotoEvento,
    textoAnalisis: textoAnalisis,
    clasificacionDetectada: tipo,
    rawVisionText: textoVision
  },
  binary: input.binary || {}
}];

const mensaje = ($input.first().json.body.content || "").toLowerCase().trim();

let comando = "desconocido";

// Detectar diferentes formas de preguntar por consultas
if (mensaje.includes("consulta") || 
    mensaje.includes("cuantas") || 
    mensaje.includes("cuantos") ||
    mensaje.includes("lista") ||
    mensaje.includes("pendiente")) {
  comando = "listar_consultas";
}

// Detectar si quiere marcar como atendida
if (mensaje.includes("atendida") || 
    mensaje.includes("completada") ||
    mensaje.includes("hecha")) {
  comando = "marcar_atendida";
}

return [{
  json: {
    comando: comando,
    mensajeOriginal: mensaje,
    conversationId: $input.first().json.body.conversation.id
  }
}];

const respuesta = $input.first().json;
const conversaciones = respuesta.data?.payload || [];
const total = conversaciones.length;

let mensaje = "";

if (total === 0) {
  mensaje = "🙏 No tienes consultas pendientes en este momento.\n\n_Cuando un cliente complete todos sus datos, apareceran aqui._";
} else {
  mensaje = `🔔 *Consultas pendientes: ${total}*\n\n`;

  conversaciones.forEach((conv, index) => {
    const nombre = conv.meta?.sender?.name || "Sin nombre";
    const telefono = conv.meta?.sender?.phone_number || "Sin teléfono";

    // Detectar tipo de servicio del último mensaje
    const mensajes = conv.messages || [];
    const mensajesCliente = mensajes.filter(m => m.message_type === 0 && m.content);
    const todosMensajes = mensajesCliente.map(m => m.content).join(" ").toLowerCase();

    let tipoServicio = "Consulta general";
    if (todosMensajes.includes("amarre")) tipoServicio = "Amarre";
    else if (todosMensajes.includes("retorno") || todosMensajes.includes("recuperar")) tipoServicio = "Retorno";
    else if (todosMensajes.includes("dominio")) tipoServicio = "Dominio";
    else if (todosMensajes.includes("alejamiento") || todosMensajes.includes("alejar")) tipoServicio = "Alejamiento";
    else if (todosMensajes.includes("endulzamiento") || todosMensajes.includes("endulzar")) tipoServicio = "Endulzamiento";
    else if (todosMensajes.includes("limpieza")) tipoServicio = "Limpieza espiritual";
    else if (todosMensajes.includes("amuleto") || todosMensajes.includes("suerte") || todosMensajes.includes("prosperidad")) tipoServicio = "Suerte/Prosperidad";
    else if (todosMensajes.includes("ex") || todosMensajes.includes("pareja") || todosMensajes.includes("esposa") || todosMensajes.includes("esposo")) tipoServicio = "Tema de pareja";

    // Buscar el primer mensaje significativo
    let resumen = "Sin detalles";
    const mensajeSignificativo = mensajesCliente.find(m => m.content && m.content.length > 20);
    if (mensajeSignificativo) {
      resumen = mensajeSignificativo.content.substring(0, 120);
      if (mensajeSignificativo.content.length > 120) resumen += "...";
    }

    mensaje += `━━━━━━━━━━━━━━━━━━━━\n`;
    mensaje += `*${index + 1}. ${nombre}*\n`;
    mensaje += `📞 ${telefono}\n`;
    mensaje += `🔮 ${tipoServicio}\n`;
    mensaje += `💬 _${resumen}_\n\n`;
  });

  mensaje += `━━━━━━━━━━━━━━━━━━━━\n`;
  mensaje += `🙏 Que la energía te acompañe`;
}

return [{
  json: {
    mensaje: mensaje,
    total: total
  }
}];

// =====================================================
// DETERMINAR MODALIDAD SEGÚN EL ÚLTIMO MENSAJE DEL CLIENTE
// =====================================================
const dataAnterior = $input.first().json;

let clienteEnvioAudio = false;

try {
  // 1. Consultar el historial completo de mensajes en Chatwoot
  const historial = $('Historial').first().json.payload || [];

  // Ordenar mensajes por fecha ascendente
  const ordenados = [...historial].sort((a, b) => (a.created_at || 0) - (b.created_at || 0));

  // Filtrar ÚNICAMENTE mensajes entrantes del cliente (message_type === 0)
  const mensajesCliente = ordenados.filter(m => m.message_type === 0 || m.message_type === "incoming");

  if (mensajesCliente.length > 0) {
    // Obtener el ÚLTIMO mensaje enviado por el cliente
    const ultimoMensajeCliente = mensajesCliente[mensajesCliente.length - 1];

    // A) Verificar si el último mensaje contiene un archivo adjunto de audio
    if (ultimoMensajeCliente.attachments && ultimoMensajeCliente.attachments.length > 0) {
      const tieneAudio = ultimoMensajeCliente.attachments.some(att => 
        att.file_type === 'audio' || 
        (att.data_url && (att.data_url.includes('.mp3') || att.data_url.includes('.ogg') || att.data_url.includes('.webm') || att.data_url.includes('.m4a')))
      );
      if (tieneAudio) clienteEnvioAudio = true;
    }

    // B) O si el contenido del texto indica que fue un audio transcrito
    if (!clienteEnvioAudio && ultimoMensajeCliente.content) {
      const txt = String(ultimoMensajeCliente.content).toLowerCase();
      if (txt.startsWith('[audio') || txt.includes('audio transcrito:')) {
        clienteEnvioAudio = true;
      }
    }
  }
} catch (e) {}

// Fallback de respaldo: Verificar si el webhook actual traía un audio
if (!clienteEnvioAudio) {
  try {
    const webhookData = $('Webhook').first().json.body || $('Webhook').first().json;
    const attachments = webhookData.attachments || webhookData.conversation?.messages?.[0]?.attachments || [];
    if (attachments.some(a => a.file_type === 'audio')) {
      clienteEnvioAudio = true;
    }
  } catch(e) {}
}

// Extraer el texto de respuesta limpio de Luna
let textoRespuesta = "";
try {
  if (dataAnterior.choices && dataAnterior.choices[0]) {
    textoRespuesta = dataAnterior.choices[0].message.content;
  } else if (dataAnterior.textoRespuesta) {
    textoRespuesta = dataAnterior.textoRespuesta;
  }
} catch (e) {}

return [{
  json: {
    ...dataAnterior,
    enviarAudio: clienteEnvioAudio,
    clienteEnvioAudio: clienteEnvioAudio,
    textoRespuesta: textoRespuesta
  }
}];

// =====================================================
// PREPARAR RESPUESTA DE LUNA PARA AUDIO
//
// Convierte el texto del chat en una locucion natural sin perder el ultimo
// dato solicitado. Tambien transforma listas numeradas ("1.", "2.") en
// conectores hablados para que la voz nunca diga "uno punto, dos punto".
// =====================================================
const textoOriginal = $("Verificar si Enviar Audio").first().json.textoRespuesta || "";

const ordinales = [
  "Primero", "Segundo", "Tercero", "Cuarto", "Quinto",
  "Sexto", "Septimo", "Octavo", "Noveno", "Decimo"
];

let textoLimpio = String(textoOriginal || "")
  .replace(/\r\n?/g, "\n")

  // Una numeracion visual se vuelve una transicion natural para la voz.
  // Se hace antes de unir las lineas para no confundir el punto con el final
  // de una oracion ni cortar el ultimo requisito.
  .replace(/^\s*(\d{1,2})[.)]\s+/gm, (_, numero) => {
    const indice = Number(numero) - 1;
    return (ordinales[indice] || "Luego") + ", ";
  })
  .replace(/^\s*[•●▪◦*-]\s+/gm, "")

  // Quitar marcadores internos y formato, conservando siempre su contenido.
  .replace(/\[?\s*MOTIVO_OK\s*\]?/gi, "")
  .replace(/\[?\s*CONSULTA_LISTA\s*\]?/gi, "")
  .replace(/\b(ja|je|ji|jo|ju|ha|he){2,}\b/gi, "")
  .replace(/[*_`~#]/g, "")
  .replace(/["'“”‘’´]/g, "")
  .replace(/[\[\]{}]/g, "")
  .replace(/\(/g, ", ")
  .replace(/\)/g, ", ")

  // Separadores y simbolos que un sintetizador suele leer de forma extrana.
  .replace(/\\/g, " ")
  .replace(/\//g, " ")
  .replace(/\|/g, " ")
  .replace(/&/g, " y ")
  .replace(/@/g, " arroba ")
  .replace(/%/g, " por ciento ")
  .replace(/\$/g, " pesos ")
  .replace(/\+/g, " mas ")
  .replace(/=/g, " igual ")
  .replace(/[<>^]/g, "")

  // Quitar emojis sin eliminar letras, tildes ni signos de puntuacion.
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, "");

// ----------------------------------------------------
// UNION NATURAL DE RENGLONES (prosodia para la voz)
// ----------------------------------------------------
// La respuesta esta formateada para leerse en pantalla; al hablarla hay que
// unirla como se habla, no como se lista:
//   1) Un renglon que termina en dos puntos seguido de varios datos se lee
//      como una sola enumeracion fluida, con punto y coma y una "y" antes del
//      ultimo dato: "enviame estos datos: una foto...; tu nombre...; y la
//      palma de tu mano derecha". Asi la voz no recita renglones sueltos.
//   2) Los demas renglones conservan una pausa propia: punto si ya la traian
//      o punto suave al unirse, para que la voz respire y no suene atropellada.
//   3) El texto despues del ultimo punto se conserva siempre: ese era el dato
//      que antes se perdia.
// ----------------------------------------------------
function sinPuntoFinal(texto) {
  return String(texto || "").replace(/[.;:\s]+$/, "");
}
function enMinusculaInicial(texto) {
  const limpio = String(texto || "");
  return /^[A-ZÁÉÍÓÚÜÑ]/.test(limpio) ? limpio.charAt(0).toLowerCase() + limpio.slice(1) : limpio;
}
function unirConPausa(renglones) {
  let salida = "";
  for (const renglon of renglones) {
    if (!salida) { salida = renglon; continue; }
    salida += /[.!?;:,]$/.test(salida.trimEnd()) ? " " + renglon : ". " + renglon;
  }
  return salida;
}

const parrafos = textoLimpio.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
const partesVoz = [];
for (const parrafo of parrafos) {
  const renglones = parrafo.split(/\n/).map(r => r.trim()).filter(Boolean);
  if (renglones.length >= 3 && /[:：]\s*$/.test(renglones[0])) {
    // Enumeracion hablada: "intro: primera cosa; segunda; y la ultima."
    const intro = sinPuntoFinal(renglones[0]) + ":";
    const datos = renglones.slice(1).map(d => enMinusculaInicial(sinPuntoFinal(d))).filter(Boolean);
    const enumeracion = datos.length === 1
      ? datos[0]
      : datos.slice(0, -1).join("; ") + "; y " + datos[datos.length - 1];
    partesVoz.push(intro + " " + enumeracion + ".");
  } else {
    partesVoz.push(unirConPausa(renglones));
  }
}

textoLimpio = partesVoz
  .filter(Boolean)
  .join(" ")
  .replace(/\.{2,}/g, ".")
  .replace(/,\s*,+/g, ",")
  .replace(/;\s*;+/g, ";")
  .replace(/([:;,])\s*\./g, "$1 ")
  .replace(/\s+([,.!?;:])/g, "$1")
  .replace(/([,.!?;:])(?=[A-Za-zÁÉÍÓÚÜÑáéíóúüñ¿¡])/g, "$1 ")
  .replace(/\s+/g, " ")
  .trim();

if (!textoLimpio) {
  textoLimpio = "Gracias por comunicarte con el Templo Místico. En un momento te atendemos.";
} else if (!/[.!?]$/.test(textoLimpio)) {
  textoLimpio += ".";
}

// Muestreo de voz: dentro de la banda recomendada por Fish Audio para habla
