// Verificar 2: Intervención humana en últimas 24h
let mensajes = [];
try {
  const respuesta = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://crmesteban.duckdns.org/api/v1/accounts/1/conversations/${conversationId}/messages?per_page=50`,
    headers: {
      'api_access_token': 'KKaF2gF4bJZvnSkqKnR42zD8'
    },
