} catch (e) {
  console.log('Error obteniendo mensajes:', e.message);
}

const ahoraSeg = Math.floor(Date.now() / 1000);
const hace24Horas = ahoraSeg - (24 * 60 * 60);

let intervencionHumana = false;
let ultimaIntervencionHumana = null;
let quienIntervino = null;

for (const msg of mensajes) {
  if (msg.message_type === 1 && msg.created_at >= hace24Horas) {
    const senderType = msg.sender?.type || "";
    const senderAvailableName = msg.sender?.available_name || "";

    const esHumano = (senderType.toLowerCase() === "user") && 
                     senderAvailableName !== "Templo Mistico";

    if (esHumano) {
      intervencionHumana = true;
      if (!ultimaIntervencionHumana || msg.created_at > ultimaIntervencionHumana) {
        ultimaIntervencionHumana = msg.created_at;
        quienIntervino = senderAvailableName || "Agente humano";
      }
    }
  }
}

if (intervencionHumana) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://crmesteban.duckdns.org/api/v1/accounts/1/conversations/${conversationId}/labels`,
      headers: {
        'Content-Type': 'application/json',
        'api_access_token': 'KKaF2gF4bJZvnSkqKnR42zD8'
      },
      body: {
        labels: ['intervencion-humana']
      },
      json: true
    });
  } catch (e) {}
}

let tiempoDesdeIntervencion = null;
if (ultimaIntervencionHumana) {
  tiempoDesdeIntervencion = Math.floor((ahoraSeg - ultimaIntervencionHumana) / 60);
}

