}];

// =====================================================
// EXTRAER CLASIFICACIÓN DE OPENAI
// =====================================================
const raw = $input.first().json;
let respuesta = "";

try {
  if (raw.choices && raw.choices[0]) {
    respuesta = raw.choices[0].message.content || "";
  }
} catch(e) {
  respuesta = "TIBIO";
}

// Limpiar la respuesta dejando solo letras mayúsculas
respuesta = respuesta.trim().toUpperCase().replace(/[^A-Z]/g, '');

let clasificacion = "TIBIO";
if (respuesta.includes("CALIENTE")) clasificacion = "CALIENTE";
else if (respuesta.includes("FRIO")) clasificacion = "FRIO";
else if (respuesta.includes("TIBIO")) clasificacion = "TIBIO";

// Extraer contexto del caso
let conversationId = "";
let nombreCliente = "Cliente";
let telefono = "";
let tipoTrabajo = "";

try {
  const cierre = $('Pulir y Auditar Respuesta').first().json;
  conversationId = cierre.conversationId || "";
