} catch(e){}

return [{
  json: {
    clasificacion,
    conversationId,
    nombreCliente,
    telefono,
    tipoTrabajo,
    esCaliente: clasificacion === "CALIENTE",
    esFrio: clasificacion === "FRIO",
    esTibio: clasificacion === "TIBIO"
  }
}];

// Obtener etiquetas actuales de la conversación
const etiquetasActuales = $input.item.json.labels || [];

// Etiquetas de clasificación a manejar
const etiquetasClasificacion = ['lead-caliente', 'lead-tibio', 'lead-frio'];

// Filtrar etiquetas que NO son de clasificación (conservarlas)
const etiquetasConservar = etiquetasActuales.filter(
  e => !etiquetasClasificacion.includes(e)
);

// Nueva etiqueta según clasificación
const clasificacion = $('Extraer Clasificacion').item.json.clasificacion;
let nuevaEtiqueta = '';

if (clasificacion === 'CALIENTE') nuevaEtiqueta = 'lead-caliente';
else if (clasificacion === 'TIBIO') nuevaEtiqueta = 'lead-tibio';
else if (clasificacion === 'FRIO') nuevaEtiqueta = 'lead-frio';

// Combinar: etiquetas conservadas + nueva clasificación
const etiquetasFinales = [...etiquetasConservar, nuevaEtiqueta];

// Verificar si subió de categoría (para log)
const eraCaliente = etiquetasActuales.includes('lead-caliente');
const ahoraCaliente = clasificacion === 'CALIENTE';
const subioACaliente = !eraCaliente && ahoraCaliente;

return {
  etiquetasFinales,
  nuevaEtiqueta,
  clasificacion: $('Extraer Clasificacion').item.json.clasificacion,
  conversationId: $('Extraer Clasificacion').item.json.conversationId,
