        yaExiste = false;
      }
    }

    if (!yaExiste) {
      const fila = {
        conversacion_id: conversacionId,
        tipo: messageType,
        contenido: contenidoMensaje || (tipoContenido !== "texto" ? `[${tipoContenido}]` : ""),
        tipo_contenido: tipoContenido,
        url_archivo: urlArchivo,
        creado_en: new Date().toISOString()
      };
