      try {
        await this.helpers.httpRequest({
          method: "POST",
          url: `${SUPABASE_URL}/rest/v1/mensajes`,
          headers: headers,
          body: [fila],
          json: true
        });
        logPasos.push("Mensaje guardado con éxito");
