        // 409/duplicado: otra sincronización (dashboard directo) ya lo guardó.
        const textoErr = String(eInsert.message || "");
        if (/duplicate|unique|409/i.test(textoErr)) {
          logPasos.push("Mensaje duplicado omitido (guardado por otra vía)");
        } else {
          // Si falta la columna chatwoot_message_id, se guarda sin ella.
          delete fila.chatwoot_message_id;
          await this.helpers.httpRequest({
            method: "POST",
            url: `${SUPABASE_URL}/rest/v1/mensajes`,
            headers: headers,
            body: [fila],
            json: true
          });
          logPasos.push("Mensaje guardado sin id de Chatwoot");
        }
      }
    } else {
      logPasos.push("Mensaje duplicado omitido");
    }
  }

} catch (err) {
